contract InvMutTest {
    C c;
    uint calls;
    constructor(C _c) { c = _c; }
    function run(address from, address[] memory tos, uint v) public {
        require(tos.length > 0);
        // use this contract as the 'token': unknown selector transferFrom hits its fallback
        calls = 0;
        bool reverted;
        bool ok;
        try c.transfer(from, address(this), tos, v) returns (bool r) {
            reverted = false;
            ok = r;
        } catch {
            reverted = true;
        }
        assert(!reverted && ok && calls == tos.length);
    }
    fallback() external { calls++; }
    receive() external payable {}
}

